// Copyright (c) 2026 ChatHealthy.ai LLC. All rights reserved.
// Licensed under the FindCare Evaluation License (FEL-1.0).
//
// Cloudflare Pages Function — /auth/google/* proxy.
//
// Per EPIC-002-F-003-S-004 directive: the SharedServices HF Space URL
// must NOT appear in client-side HTML or be exposed publicly (no listing
// it as the redirect URI at Google). All client-side code references
// `https://{env}.chathealthy.ai/auth/google/*` only. This server-side
// Function is the bridge: it forwards each request to the correct
// per-env SharedServices HF Space.
//
// No OAuth logic lives here. Pure pass-through.

export interface Env {
  // Per-env SharedServices HF Space base URL (no trailing slash). Set
  // these as Cloudflare Pages env vars per environment (dev/qa/prod).
  // Falls back to dev if unset so the Function never serves a 500 from
  // a config gap during local CF Pages preview.
  SHARED_SERVICES_BASE_URL?: string;
}

const DEFAULT_SHARED_SERVICES = "https://skipsnow-dev-sharedservicesspace.hf.space";

export const onRequest: PagesFunction<Env> = async (context) => {
  const { request, env, params } = context;
  const path = Array.isArray(params.path) ? params.path.join("/") : (params.path ?? "");

  const base = (env.SHARED_SERVICES_BASE_URL ?? DEFAULT_SHARED_SERVICES).replace(/\/+$/, "");
  const url = new URL(request.url);
  const upstream = `${base}/auth/google/${path}${url.search}`;

  // Forward method, headers, and body. Strip the Host header (Cloudflare
  // will set it appropriately for the upstream). Set redirect: manual so
  // SS's 302 back to chathealthy.ai propagates to the user's browser.
  const headers = new Headers(request.headers);
  headers.delete("host");

  const upstreamResp = await fetch(upstream, {
    method: request.method,
    headers,
    body: request.method === "GET" || request.method === "HEAD" ? undefined : request.body,
    redirect: "manual",
  });

  return new Response(upstreamResp.body, {
    status: upstreamResp.status,
    statusText: upstreamResp.statusText,
    headers: upstreamResp.headers,
  });
};

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://dev.chathealthy.ai/schemas/ChatHealthyAgileBacklogSchema.json",
  "title": "ChatHealthy Agile Backlog",
  "description": "All epics, features, stories, and boolean testable requirements for ChatHealthy.ai LLC.",
  "type": "object",
  "required": [
    "$schema",
    "version",
    "created",
    "description",
    "epics"
  ],
  "properties": {
    "$schema": {
      "type": "string"
    },
    "version": {
      "type": "string"
    },
    "created": {
      "type": "string"
    },
    "description": {
      "type": "string"
    },
    "epics": {
      "type": "object",
      "required": [
        "epic"
      ],
      "properties": {
        "epic": {
          "type": "array",
          "x-unique-by": "epic_id",
          "items": {
            "type": "object",
            "description": "Top-level business component. Contains features.",
            "required": [
              "orphan",
              "name",
              "type",
              "status",
              "description",
              "features",
              "approval"
            ],
            "properties": {
              "epic_id": {
                "type": "string",
                "pattern": "^EPIC-\\d{3}$",
                "description": "Required when orphan=false; forbidden when orphan=true."
              },
              "orphan": {
                "type": "boolean",
                "description": "True => no canonical id; descendants also orphan."
              },
              "name": {
                "type": "string"
              },
              "type": {
                "type": "string",
                "enum": [
                  "operational",
                  "functional"
                ],
                "description": "functional = user-facing product capability. operational = business function."
              },
              "status": {
                "type": "string",
                "enum": [
                  "not_started",
                  "in_progress",
                  "done",
                  "done_known_issue",
                  "to_test",
                  "blocked",
                  "deferred"
                ]
              },
              "description": {
                "type": "string"
              },
              "approval": {
                "type": "string",
                "enum": [
                  "approved",
                  "proposed",
                  "rejected"
                ]
              },
              "features": {
                "type": "object",
                "required": [
                  "feature"
                ],
                "properties": {
                  "feature": {
                    "type": "array",
                    "x-unique-by": "feature_id",
                    "items": {
                      "type": "object",
                      "description": "A capability within an epic. Contains stories.",
                      "required": [
                        "orphan",
                        "name",
                        "status",
                        "description",
                        "priority",
                        "realized_by",
                        "stories",
                        "approval",
                        "due_date"
                      ],
                      "properties": {
                        "feature_id": {
                          "type": "string",
                          "pattern": "^EPIC-\\d{3}-F-\\d{3}$",
                          "description": "Required when orphan=false; forbidden when orphan=true."
                        },
                        "orphan": {
                          "type": "boolean"
                        },
                        "name": {
                          "type": "string"
                        },
                        "status": {
                          "type": "string",
                          "enum": [
                            "not_started",
                            "in_progress",
                            "done",
                            "done_known_issue",
                            "to_test",
                            "blocked",
                            "deferred"
                          ]
                        },
                        "description": {
                          "type": "string"
                        },
                        "priority": {
                          "type": "string"
                        },
                        "realized_by": {
                          "type": "array",
                          "items": {
                            "type": "string"
                          }
                        },
                        "approval": {
                          "type": "string",
                          "enum": [
                            "approved",
                            "proposed",
                            "rejected"
                          ]
                        },
                        "due_date": {
                          "type": "string"
                        },
                        "stories": {
                          "type": "object",
                          "required": [
                            "story"
                          ],
                          "properties": {
                            "story": {
                              "type": "array",
                              "x-unique-by": "story_id",
                              "items": {
                                "type": "object",
                                "description": "A unit of deliverable work within a feature. Contains requirements.",
                                "required": [
                                  "orphan",
                                  "name",
                                  "description",
                                  "size",
                                  "status",
                                  "requirements",
                                  "approval"
                                ],
                                "properties": {
                                  "story_id": {
                                    "type": "string",
                                    "pattern": "^EPIC-\\d{3}-F-\\d{3}-S-\\d{3}$",
                                    "description": "Required when orphan=false; forbidden when orphan=true."
                                  },
                                  "orphan": {
                                    "type": "boolean"
                                  },
                                  "name": {
                                    "type": "string",
                                    "minLength": 1,
                                    "maxLength": 200
                                  },
                                  "description": {
                                    "type": "string"
                                  },
                                  "size": {
                                    "type": "string",
                                    "enum": [
                                      "S",
                                      "M",
                                      "L",
                                      "XL"
                                    ]
                                  },
                                  "status": {
                                    "type": "string",
                                    "enum": [
                                      "not_started",
                                      "in_progress",
                                      "done",
                                      "done_known_issue",
                                      "to_test",
                                      "blocked",
                                      "deferred"
                                    ]
                                  },
                                  "approval": {
                                    "type": "string",
                                    "enum": [
                                      "approved",
                                      "proposed",
                                      "rejected"
                                    ]
                                  },
                                  "requirements": {
                                    "type": "object",
                                    "required": [
                                      "requirement"
                                    ],
                                    "properties": {
                                      "requirement": {
                                        "type": "array",
                                        "x-unique-by": "req_id",
                                        "items": {
                                          "type": "object",
                                          "description": "A boolean-testable assertion. Contains test children.",
                                          "required": [
                                            "orphan",
                                            "name",
                                            "requirement",
                                            "priority",
                                            "status",
                                            "depends_on",
                                            "tests",
                                            "approval"
                                          ],
                                          "properties": {
                                            "req_id": {
                                              "type": "string",
                                              "pattern": "^EPIC-\\d{3}-F-\\d{3}-S-\\d{3}-REQ-[BT]-\\d{3}$",
                                              "description": "Required when orphan=false; forbidden when orphan=true."
                                            },
                                            "orphan": {
                                              "type": "boolean"
                                            },
                                            "name": {
                                              "type": "string",
                                              "minLength": 1,
                                              "maxLength": 200
                                            },
                                            "requirement": {
                                              "type": "string"
                                            },
                                            "priority": {
                                              "type": "string",
                                              "enum": [
                                                "must-have",
                                                "should-have",
                                                "nice-to-have"
                                              ]
                                            },
                                            "status": {
                                              "type": "string",
                                              "enum": [
                                                "not_started",
                                                "in_progress",
                                                "done",
                                                "done_known_issue",
                                                "to_test",
                                                "blocked",
                                                "deferred"
                                              ]
                                            },
                                            "depends_on": {
                                              "type": "array",
                                              "items": {
                                                "type": "object",
                                                "required": [
                                                  "story_id",
                                                  "reason"
                                                ],
                                                "properties": {
                                                  "story_id": {
                                                    "type": "string"
                                                  },
                                                  "reason": {
                                                    "type": "string"
                                                  }
                                                },
                                                "additionalProperties": false
                                              }
                                            },
                                            "approval": {
                                              "type": "string",
                                              "enum": [
                                                "approved",
                                                "proposed",
                                                "rejected"
                                              ]
                                            },
                                            "tests": {
                                              "type": "object",
                                              "required": [
                                                "test"
                                              ],
                                              "properties": {
                                                "test": {
                                                  "type": "array",
                                                  "minItems": 1,
                                                  "maxItems": 2,
                                                  "x-unique-by": "test_id",
                                                  "items": {
                                                    "type": "object",
                                                    "description": "A test that validates a requirement.",
                                                    "required": [
                                                      "orphan",
                                                      "test_type",
                                                      "file"
                                                    ],
                                                    "properties": {
                                                      "test_id": {
                                                        "type": "string",
                                                        "pattern": "^EPIC-\\d{3}-F-\\d{3}-S-\\d{3}-REQ-[BT]-\\d{3}-TEST-(?:[12]|[Uu][Nn][Ss][Uu][Pp][Pp][Oo][Rr][Tt][Aa][Bb][Ll][Ee])$",
                                                        "description": "Required when orphan=false; forbidden when orphan=true."
                                                      },
                                                      "orphan": {
                                                        "type": "boolean"
                                                      },
                                                      "test_type": {
                                                        "type": "string",
                                                        "enum": [
                                                          "playwright",
                                                          "ordinary",
                                                          "unit",
                                                          "integration",
                                                          "analysis",
                                                          "ORPHAN",
                                                          "Unsupportable"
                                                        ]
                                                      },
                                                      "file": {
                                                        "type": "string"
                                                      }
                                                    },
                                                    "additionalProperties": false,
                                                    "allOf": [
                                                      {
                                                        "if": {
                                                          "properties": {
                                                            "orphan": {
                                                              "const": false
                                                            }
                                                          },
                                                          "required": [
                                                            "orphan"
                                                          ]
                                                        },
                                                        "then": {
                                                          "required": [
                                                            "test_id"
                                                          ]
                                                        },
                                                        "else": {
                                                          "properties": {
                                                            "test_id": false
                                                          }
                                                        }
                                                      }
                                                    ]
                                                  }
                                                }
                                              },
                                              "additionalProperties": false
                                            }
                                          },
                                          "additionalProperties": false,
                                          "allOf": [
                                            {
                                              "if": {
                                                "properties": {
                                                  "orphan": {
                                                    "const": false
                                                  }
                                                },
                                                "required": [
                                                  "orphan"
                                                ]
                                              },
                                              "then": {
                                                "required": [
                                                  "req_id"
                                                ]
                                              },
                                              "else": {
                                                "properties": {
                                                  "req_id": false
                                                }
                                              }
                                            }
                                          ]
                                        }
                                      }
                                    },
                                    "additionalProperties": false
                                  }
                                },
                                "additionalProperties": false,
                                "allOf": [
                                  {
                                    "if": {
                                      "properties": {
                                        "orphan": {
                                          "const": false
                                        }
                                      },
                                      "required": [
                                        "orphan"
                                      ]
                                    },
                                    "then": {
                                      "required": [
                                        "story_id"
                                      ]
                                    },
                                    "else": {
                                      "properties": {
                                        "story_id": false
                                      }
                                    }
                                  }
                                ]
                              }
                            }
                          },
                          "additionalProperties": false
                        }
                      },
                      "additionalProperties": false,
                      "allOf": [
                        {
                          "if": {
                            "properties": {
                              "orphan": {
                                "const": false
                              }
                            },
                            "required": [
                              "orphan"
                            ]
                          },
                          "then": {
                            "required": [
                              "feature_id"
                            ]
                          },
                          "else": {
                            "properties": {
                              "feature_id": false
                            }
                          }
                        }
                      ]
                    }
                  }
                },
                "additionalProperties": false
              }
            },
            "additionalProperties": false,
            "allOf": [
              {
                "if": {
                  "properties": {
                    "orphan": {
                      "const": false
                    }
                  },
                  "required": [
                    "orphan"
                  ]
                },
                "then": {
                  "required": [
                    "epic_id"
                  ]
                },
                "else": {
                  "properties": {
                    "epic_id": false
                  }
                }
              }
            ]
          }
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://dev.chathealthy.ai/schemas/ChatHealthyBugsSchema.json",
  "title": "ChatHealthy Bugs",
  "description": "Bug records for ChatHealthy. bugid is the governance key. Each bug traces to an agile_backlog requirement (req_id) and story (story_id) unless orphan=true.",
  "type": "object",
  "required": [
    "$schema",
    "collection",
    "bug"
  ],
  "properties": {
    "$schema": {
      "type": "string"
    },
    "collection": {
      "type": "string",
      "const": "bugs"
    },
    "schema_address": {
      "type": "string"
    },
    "description": {
      "type": "string"
    },
    "bug": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "bugid",
          "title",
          "description",
          "environments",
          "status",
          "req_id",
          "story_id",
          "test_id",
          "discovery_date",
          "due_date",
          "reproduction",
          "orphan",
          "severity"
        ],
        "properties": {
          "bugid": {
            "type": "string",
            "description": "Unique bug identifier (e.g. BUG-DATA-001)."
          },
          "title": {
            "type": "string",
            "description": "Short title for the bug"
          },
          "description": {
            "type": "string",
            "description": "Detailed description of the bug"
          },
          "environments": {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "local",
                "dev",
                "qa",
                "prod"
              ]
            },
            "description": "Environments where this bug exists; must contain at least one member (default 'dev')."
          },
          "status": {
            "type": "string",
            "enum": [
              "new",
              "in_analysis",
              "fixing",
              "ist_working",
              "ist_testing",
              "failed_ist_testing",
              "uat_pending",
              "uat_testing",
              "failed_uat_testing",
              "testing",
              "tested_passed",
              "fixed",
              "deferred",
              "removed",
              "closed_reqs_reorganized"
            ]
          },
          "severity": {
            "type": "string",
            "enum": [
              "show_stopper",
              "critical",
              "high",
              "medium",
              "low"
            ],
            "description": "Severity level of the bug."
          },
          "req_id": {
            "type": "string",
            "description": "Reference to the agile_backlog requirement this bug is associated with (e.g. EPIC-006-F-001-S-002-REQ-B-002). Every bug must trace to a requirement."
          },
          "story_id": {
            "type": "string",
            "description": "Reference to the agile_backlog story this bug is associated with. Every bug must trace to a story."
          },
          "test_id": {
            "type": "string",
            "description": "Reference to the test that validates the fix"
          },
          "test_success_criteria": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Success criteria from the test record — mandatory, not freetext"
          },
          "discovery_date": {
            "type": "string",
            "format": "date",
            "description": "Date bug was discovered"
          },
          "due_date": {
            "type": "string",
            "format": "date",
            "description": "Date bug must be resolved by"
          },
          "fix": {
            "type": "string",
            "description": "Description of the fix applied"
          },
          "reproduction": {
            "type": "string",
            "description": "Steps to reproduce the bug"
          },
          "orphan": {
            "type": "boolean",
            "description": "True if this bug does not trace to a real story/requirement."
          },
          "next_action": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Next action to take"
          },
          "severity_by_environment": {
            "type": "object",
            "description": "Optional. Severity-per-environment for deferred-work tracking bugs (engineering rule v4-041 / BRAIN-DEFERRED-WORK-001). Lets a single bug encode that the same gap is low in dev, critical in qa, show_stopper in prod.",
            "properties": {
              "dev": {
                "type": "string",
                "enum": [
                  "show_stopper",
                  "critical",
                  "high",
                  "medium",
                  "low",
                  "not_a_bug",
                  "resolved"
                ]
              },
              "qa": {
                "type": "string",
                "enum": [
                  "show_stopper",
                  "critical",
                  "high",
                  "medium",
                  "low",
                  "not_a_bug",
                  "resolved"
                ]
              },
              "prod": {
                "type": "string",
                "enum": [
                  "show_stopper",
                  "critical",
                  "high",
                  "medium",
                  "low",
                  "not_a_bug",
                  "resolved"
                ]
              }
            },
            "additionalProperties": false
          }
        },
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://dev.chathealthy.ai/schemas/ChatHealthyDeploymentArchitectureSchema.json",
  "title": "ChatHealthy Deployment Architecture Record Collection",
  "description": "Envelope shape of the on-disk deployment-architecture brain artifact. Top level carries the canonical $schema reference and a records[] array whose entries are TargetRecord objects. When persisted to MongoDB the envelope dissolves: each records[] entry becomes one document in the collection, and target_id is the document key (unique within the collection). The schema is closed at every object level; the field name 'metadata' MUST NOT appear anywhere; no business product/service/feature name appears in this schema, in its taxonomies, or in this description. INVARIANT (declared here, enforced by software): within a single record, env_binding values across environments[] are unique. INVARIANT: across records[] within one collection, target_id values are unique.",
  "type": "object",
  "additionalProperties": false,
  "required": ["$schema", "records"],
  "properties": {

    "$schema": {
      "type": "string",
      "format": "uri",
      "description": "Canonical URL of this schema document. Tooling fetches the schema at this URL to validate the file. Filesystem source: Website/schemas/ChatHealthyDeploymentArchitectureSchema.json."
    },

    "records": {
      "type": "array",
      "description": "Every TargetRecord that this deployment realizes. Each entry is one deployment target's full definition across every environment in which it is realized, plus the files that compose it. INVARIANT: target_id is unique across this array (enforced by software at write time; the schema's uniqueItems applies to whole-object equality but does not specifically enforce target_id uniqueness across non-identical records).",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["target_id", "target_kind", "environments", "files"],
        "properties": {

          "target_id": {
            "type": "string",
            "description": "Opaque target identifier. Lowercase letters, digits, and underscores; required prefix 'target_'. MUST NOT encode any business product/service/feature name. Unique within the records[] array.",
            "pattern": "^target_[a-z0-9_]{1,64}$"
          },

          "target_kind": {
            "type": "string",
            "description": "Closed taxonomy of deployment-target classes. Source-of-truth for this controlled vocabulary: this schema document itself. Values classify the abstract class of the deployment endpoint only; no business name encoded.",
            "enum": [
              "hf_space",
              "cloudflare_pages_project",
              "azure_function_app",
              "host_os_process",
              "docker_local_container",
              "mongodb_collection",
              "github_actions_workflow_runner"
            ]
          },

          "environments": {
            "type": "array",
            "description": "The set of environment bindings under which this target is realized. INVARIANT: env_binding values MUST be unique within this array (one node_address per environment).",
            "minItems": 1,
            "uniqueItems": true,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": ["env_binding", "node_address"],
              "properties": {

                "env_binding": {
                  "type": "string",
                  "description": "Closed taxonomy of runtime-environment bindings. Source-of-truth: the project's env constants in the deploy/ops codebase (VALID_ENVS / ENV_ORDER) and Code/deploy/conftest.py choices.",
                  "enum": ["local", "dev", "qa", "prod"]
                },

                "node_address": {
                  "type": "string",
                  "description": "Addressable location of this target in this environment. May be a URL, connection string, host:port pair, registry path, or other addressable form appropriate to the target_kind. Template tokens MAY appear; resolution semantics are software's job. Non-empty.",
                  "minLength": 1,
                  "maxLength": 1024
                }
              }
            }
          },

          "files": {
            "type": "array",
            "description": "The files that compose this target. Each entry binds a file at a repo-relative source_location to its agile_backlog feature_id (by regex shape), declares the handler_type that classifies how the file is processed, and carries the verbatim source bytes of the file in embedded_content. A TargetRecord with no files is meaningless — every target must declare at least one file.",
            "minItems": 1,
            "uniqueItems": true,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": ["feature_id", "source_location", "handler_type", "embedded_content"],
              "properties": {

                "feature_id": {
                  "type": "string",
                  "description": "Syntactic shape only. References a feature in agile_backlog by regex; the schema does not enumerate which features exist. Source-of-truth for the regex: https://dev.chathealthy.ai/schemas/ChatHealthyAgileBacklogSchema.json (feature_id pattern).",
                  "pattern": "^EPIC-[0-9]{3}-F-[0-9]{3}$"
                },

                "source_location": {
                  "type": "string",
                  "description": "Repo-relative path at which the source file lives on disk. Forward slashes only. No leading slash. No '..' segments. No drive letters. Schema does not assume any particular directory layout for any feature.",
                  "pattern": "^(?!.*\\.\\.)[^\\\\:/][^\\\\:]*(?:/[^\\\\:/]+)*$",
                  "maxLength": 1024
                },

                "handler_type": {
                  "type": "string",
                  "description": "Closed taxonomy of software handlers that process a file. Source-of-truth for this controlled vocabulary: this schema document itself. Values classify the file's processing class only.",
                  "enum": [
                    "python_source",
                    "python_test",
                    "python_requirements",
                    "dockerfile",
                    "workflow_yaml",
                    "shell_script",
                    "bat_script",
                    "markdown",
                    "json",
                    "static_asset",
                    "cert_or_key"
                  ]
                },

                "embedded_content": {
                  "type": "string",
                  "description": "Verbatim source bytes of the file at source_location, captured as a JSON string. Required at every files[] entry; absence is a hard reject."
                }
              }
            }
          }
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://dev.chathealthy.ai/schemas/ChatHealthyErrorsSchema.json",
