}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://dev.chathealthy.ai/schemas/ChatHealthyProvidersSchema.json",
  "title": "Providers",
  "description": "A bundle of healthcare provider records. The Providers wrapper holds a 'provider' array. To use the inner provider as a MongoDB $jsonSchema collection validator, target '#/definitions/provider' and replace 'type' with 'bsonType' throughout. Only npi is required; every other field is optional. Patterns and enums constrain the shape of values that are present.",
  "type": "object",
  "required": ["Providers"],
  "properties": {
    "Providers": {
      "type": "object",
      "required": ["provider"],
      "properties": {
        "provider": {
          "description": "Array of provider records. May be empty.",
          "type": "array",
          "items": { "$ref": "#/definitions/provider" }
        }
      },
      "additionalProperties": false
    }
  },
  "definitions": {
    "provider": {
      "title": "Provider",
      "description": "A healthcare provider record sourced from the NPPES NPI Registry, enriched with county data. Only npi is required.",
      "type": "object",
      "required": ["npi"],
      "properties": {
        "_id": {
          "description": "MongoDB ObjectId — auto-assigned on insert. Omit on write; always present on read.",
          "type": "object"
        },
        "npi": {
          "description": "National Provider Identifier — 10-digit string, globally unique, issued by CMS. Never numeric; leading zeros are significant.",
          "type": "string",
          "pattern": "^[0-9]{10}$",
          "examples": ["1144247073", "1215954557"]
        },
        "entity_type_code": {
          "description": "NPI entity type. '1' = individual practitioner. '2' = organization (hospital, pharmacy, group practice, etc.).",
          "type": "string",
          "enum": ["1", "2"]
        },
        "provider_enumeration_date": {
          "description": "Date the NPI was issued by CMS. Format: MM/DD/YYYY (as received from NPPES CSV; not converted to ISO 8601).",
          "type": "string",
          "pattern": "^[0-9]{2}/[0-9]{2}/[0-9]{4}$",
          "examples": ["07/16/2006"]
        },
        "last_update_date": {
          "description": "Date the NPI record was last updated in the NPPES registry. Format: MM/DD/YYYY.",
          "type": "string",
          "pattern": "^[0-9]{2}/[0-9]{2}/[0-9]{4}$"
        },
        "certification_date": {
          "description": "Date the provider last certified their NPI record with CMS. Format: MM/DD/YYYY.",
          "type": "string",
          "pattern": "^[0-9]{2}/[0-9]{2}/[0-9]{4}$"
        },
        "npi_deactivation_date": {
          "description": "Date the NPI was deactivated. Present only if the provider has been deactivated. Format: MM/DD/YYYY. If present without npi_reactivation_date, the provider is inactive and flagged as out_of_scope.",
          "type": "string",
          "pattern": "^[0-9]{2}/[0-9]{2}/[0-9]{4}$"
        },
        "npi_reactivation_date": {
          "description": "Date the NPI was reactivated after a prior deactivation. Format: MM/DD/YYYY.",
          "type": "string",
          "pattern": "^[0-9]{2}/[0-9]{2}/[0-9]{4}$"
        },
        "practice_address": {
          "description": "Provider practice locations. Either a single address (one location) or an array of addresses (one per location). Index 0 of the array is the primary practice location.",
          "oneOf": [
            { "$ref": "#/definitions/address" },
            { "type": "array", "items": { "$ref": "#/definitions/address" } }
          ]
        },
        "mailing_address": {
          "$ref": "#/definitions/address",
          "description": "Mailing/billing address. May differ from practice_address. Used as fallback geocoding input in Pass 3 (billing retry)."
        },
        "taxonomies": {
          "description": "Provider specialty taxonomy codes (NUCC Health Care Provider Taxonomy). Multiple entries represent additional specialties. Exactly one entry should have primary: true when present.",
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "code": {
                "description": "NUCC taxonomy code. 10-character alphanumeric string.",
                "type": "string",
                "pattern": "^[A-Z0-9]{10}$",
                "examples": ["207R00000X", "333600000X"]
              },
              "primary": {
                "description": "True if this is the provider's primary specialty.",
                "type": "boolean"
              },
              "group": {
                "description": "Optional taxonomy group label.",
                "type": "string"
              }
            }
          }
        },
        "licenses": {
          "description": "Professional licenses held by the provider. Each entry is a state/number pair from the NPPES data.",
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "state": {
                "description": "US state abbreviation where the license was issued.",
                "type": "string",
                "pattern": "^[A-Z]{2}$"
              },
              "number": {
                "description": "License number as reported by the provider to CMS.",
                "type": "string"
              }
            }
          }
        },
        "other_identifiers": {
          "description": "Legacy or alternate provider identifiers (e.g. UPIN, Medicaid, Medicare OSCAR). Parallel array with other_identifier_types and other_identifier_states.",
          "type": "array",
          "items": { "type": "string" }
        },
        "other_identifier_types": {
          "description": "Type codes for other_identifiers. Common values: '01' = Other, '04' = Medicare UPIN, '05' = Medicaid.",
          "type": "array",
          "items": { "type": "string" }
        },
        "other_identifier_states": {
          "description": "State associated with each entry in other_identifiers.",
          "type": "array",
          "items": { "type": "string" }
        },
        "other_identifier_issuers": {
          "description": "Issuing organization for each entry in other_identifiers.",
          "type": "array",
          "items": { "type": "string" }
        },
        "county": {
          "$ref": "#/definitions/county",
          "description": "Doc-level county enrichment result. Records with multiple practice locations also carry a county sub-document on each practice_address element and on mailing_address."
        },
        "bad_data": {
          "description": "Set when a provider record fails a data-quality gate. Present only when flagged.",
          "type": "object",
          "properties": {
            "flagged": {
              "description": "True when the record is flagged. Permanent until source data is corrected.",
              "type": "boolean"
            },
            "reason": {
              "description": "Why the record was flagged. Controlled vocabulary.",
              "type": "string"
            }
          }
        },
        "out_of_scope": {
          "description": "Set when a provider record is excluded from operational scope (deactivated, foreign, no usable address, etc.).",
          "type": "object",
          "properties": {
            "flagged": {
              "description": "True when the record is excluded.",
              "type": "boolean"
            },
            "reason": {
              "description": "Why the record was excluded. Controlled vocabulary.",
              "type": "string"
            }
          }
        },
        "load_id": {
          "description": "Pipeline run identifier that wrote this record. Format: '<uuid>:<worker_num>' (sub-orchestrator instance id with the worker suffix).",
          "type": "string",
          "examples": ["ea36237b-377c-4888-8fa9-5faab71e4820:0"]
        },
        "record_id": {
          "description": "Sequential integer assigned by the load worker. Unique within a single pipeline run but NOT globally unique across runs — use npi as the stable identifier.",
          "type": "integer",
          "minimum": 0
        },
        "worker_id": {
          "description": "Index of the pipeline worker that loaded this record. Used for debugging load distribution.",
          "type": "integer",
          "minimum": 0
        },
        "provider_last_name_legal_name": {
          "description": "Provider's legal last name as registered with CMS. Typically present on individual records (entity_type_code = '1').",
          "type": "string"
        },
        "provider_first_name": {
          "description": "Provider's first name. Typically present on individual records.",
          "type": "string"
        },
        "provider_middle_name": {
          "description": "Provider's middle name or initial.",
          "type": "string"
        },
        "provider_name_prefix_text": {
          "description": "Name prefix (e.g. 'Dr.', 'Mr.').",
          "type": "string"
        },
        "provider_name_suffix_text": {
          "description": "Name suffix (e.g. 'Jr.', 'III').",
          "type": "string"
        },
        "provider_credential_text": {
          "description": "Professional credential suffix (e.g. 'M.D.', 'D.O.', 'R.N.').",
          "type": "string",
          "examples": ["M.D.", "D.O.", "R.N.", "Ph.D."]
        },
        "provider_sex_code": {
          "description": "Provider sex as reported to CMS.",
          "type": "string",
          "enum": ["M", "F"]
        },
        "is_sole_proprietor": {
          "description": "Whether the individual provider operates as a sole proprietor ('Y'/'N'). Typically present on individual records.",
          "type": "string",
          "enum": ["Y", "N"]
        },
        "provider_organization_name_legal_business_name": {
          "description": "Legal business name of the organization. Typically present on organization records (entity_type_code = '2').",
          "type": "string",
          "examples": ["WALMART INC.", "MAYO CLINIC"]
        },
        "provider_other_organization_name": {
          "description": "Alternate or DBA name for the organization.",
          "type": "string"
        },
        "provider_other_organization_name_type_code": {
          "description": "Type code for provider_other_organization_name.",
          "type": "string",
          "enum": ["3", "4", "5", "6"]
        },
        "employer_identification_number_ein": {
          "description": "Federal EIN for the organization. May be '<UNAVAIL>' if CMS could not obtain it.",
          "type": "string"
        },
        "is_organization_subpart": {
          "description": "Whether this organization is a subpart of a larger organization ('Y'/'N').",
          "type": "string",
          "enum": ["Y", "N"]
        },
        "parent_organization_lbn": {
          "description": "Legal business name of the parent organization.",
          "type": "string"
        },
        "parent_organization_tin": {
          "description": "Tax Identification Number of the parent organization.",
          "type": "string"
        },
        "authorized_official_last_name": {
          "description": "Last name of the authorized official responsible for the NPI record.",
          "type": "string"
        },
        "authorized_official_first_name": {
          "description": "First name of the authorized official.",
          "type": "string"
        },
        "authorized_official_middle_name": {
          "description": "Middle name of the authorized official.",
          "type": "string"
        },
        "authorized_official_title_or_position": {
          "description": "Job title or position of the authorized official.",
          "type": "string",
          "examples": ["DIRECTOR OF HEALTHCARE CONTRACTING", "CEO", "CHIEF MEDICAL OFFICER"]
        },
        "authorized_official_telephone_number": {
          "description": "Phone number of the authorized official. Digits only, no formatting.",
          "type": "string"
        },
        "authorized_official_credential_text": {
          "description": "Professional credential of the authorized official.",
          "type": "string"
        },
        "embedding": {
          "description": "Vector embedding of the provider record for semantic search.",
          "type": "array",
          "items": { "type": "number" }
        },
        "embedding_text": {
          "description": "Text source used to generate the embedding (truncated for storage efficiency).",
          "type": "string"
        },
        "embedding_model": {
          "description": "Identifier of the embedding model used (e.g. 'text-embedding-3-large').",
          "type": "string"
        },
        "embedding_version": {
          "description": "Version stamp of the embedding pipeline that produced this vector.",
          "type": "string"
        }
      }
    },
    "address": {
      "title": "Address",
      "description": "A US mailing or practice address as reported in the NPPES NPI registry. May carry a nested county sub-document (per-address county enrichment, post-multi-practice-address migration).",
      "type": "object",
      "properties": {
        "line1": {
          "description": "Street address line 1.",
          "type": "string"
        },
        "line2": {
          "description": "Street address line 2 (suite, floor, etc.).",
          "type": "string"
        },
        "city": {
          "description": "City name.",
          "type": "string"
        },
        "state": {
          "description": "Two-letter US state or territory abbreviation.",
          "type": "string",
          "pattern": "^[A-Z]{2}$"
        },
        "zip": {
          "description": "ZIP code. May be 5-digit ('30024') or ZIP+4 ('30024-1234'). Stored as a string to preserve leading zeros.",
          "type": "string",
          "pattern": "^[0-9]{5}(-[0-9]{4})?$"
        },
        "country": {
          "description": "ISO 3166-1 alpha-2 country code. 'US' for domestic providers. Foreign values trigger out_of_scope with reason 'foreign_provider'.",
          "type": "string",
          "pattern": "^[A-Z]{2}$",
          "examples": ["US"]
        },
        "phone": {
          "description": "Phone number as reported by NPPES. May be digits only or include formatting.",
          "type": "string"
        },
        "phone_ext": {
          "description": "Phone number extension.",
          "type": "string"
        },
        "fax": {
          "description": "Fax number as reported by NPPES.",
          "type": "string"
        },
        "county": {
          "$ref": "#/definitions/county",
          "description": "Per-address county enrichment result. Present on practice_address elements (and mailing_address) in records produced after the multi-practice-address migration."
        }
      }
    },
    "county": {
      "title": "CountyEnrichment",
      "description": "Result of the county enrichment pipeline. Sits at the document level (legacy) OR nested per-address (post-multi-practice-address migration). Includes a derived urban flag from the U.S. Census 2020 county urban-rural tabulation.",
      "type": "object",
      "properties": {
        "fips": {
          "description": "5-digit FIPS county code (2-digit state + 3-digit county). Null when enrichment failed (geocoder_failed) or provider/address is excluded (out_of_scope*). Example: '30063' = Missoula County, MT.",
          "type": ["string", "null"],
          "pattern": "^[0-9]{5}$"
        },
        "name": {
          "description": "Human-readable county name (e.g. 'Missoula County'). Present when fips is set via crosswalk or Maps. Absent for some sources (e.g. Census batch geocoder does not return county name).",
          "type": "string"
        },
        "source": {
          "description": "Which enrichment pass assigned the county. Determines reliability and method of the assignment.",
          "type": "string",
          "enum": [
            "crosswalk_pass1",
            "crosswalk_zip_fixed",
            "geocoder_pass2_batch",
            "geocoder_pass2_batch_billing",
            "geocoder_pass3_billing",
            "geocoder_pass4_maps",
            "geocoder_pass5_maps_billing",
            "geocoder_pass6_nppes",
            "geocoder_failed",
            "geocoder_no_address",
            "out_of_scope",
            "out_of_scope_zip_state_mismatch"
          ],
          "x-enum-descriptions": {
            "crosswalk_pass1": "ZIP -> county via ZipCountyCrosswalk (res_ratio >= 0.98). Fastest path, ~82% of providers.",
            "crosswalk_zip_fixed": "ZIP crosswalk applied after zip_state_mismatch detection corrected the state.",
            "geocoder_pass2_batch": "U.S. Census Geocoder batch API on practice address.",
            "geocoder_pass2_batch_billing": "U.S. Census Geocoder batch API on practice address with mailing fallback (legacy combined Pass 2 path).",
            "geocoder_pass3_billing": "U.S. Census Geocoder batch API on mailing/billing address (Pass 2 fallback).",
            "geocoder_pass4_maps": "Google Maps Geocoding API on practice address. Paid API.",
            "geocoder_pass5_maps_billing": "Google Maps Geocoding API on billing address. Paid API.",
            "geocoder_pass6_nppes": "NPI looked up in NPPES registry; returned address tried against ZIP crosswalk.",
            "geocoder_failed": "All enrichment passes exhausted without a result.",
            "geocoder_no_address": "Element has no usable line1 / city to geocode.",
            "out_of_scope": "Address (or provider) excluded from enrichment. See 'reason' for the criterion.",
            "out_of_scope_zip_state_mismatch": "Per-address flag: this address's ZIP does not match its state and license-based repair did not resolve it."
          }
        },
        "reason": {
          "description": "Exclusion reason. Present when source = 'out_of_scope' or 'out_of_scope_zip_state_mismatch'. Controlled vocabulary; new values may be added without schema churn.",
          "type": "string"
        },
        "zip_ratio": {
          "description": "Residential ratio of the ZIP code used for crosswalk assignment (0.0 - 1.0). Present only when source = 'crosswalk_pass1'.",
          "type": "number",
          "minimum": 0.0,
          "maximum": 1.0
        },
        "urban": {
          "description": "Urban-vs-rural classification of the county. True = urban (>=50% of county population in 2020 Census urban areas). Derived from U.S. Census 2020_UA_COUNTY tabulation per EPIC-010-F-007-S-011-REQ-T-002.",
          "type": "boolean"
        }
      }
    }
  }
}

{
