                        "req_id"
                      ],
                      "properties": {
                        "statement_number": {
                          "type": "integer",
                          "minimum": 1,
                          "description": "Sequential integer starting at 1 within the rule."
                        },
                        "statement_body": {
                          "type": "string",
                          "minLength": 1,
